import re
DIR='D:/SpaceBook/SpaceBook Web/docs/source-verification/class-8/pashto/pages/'
def addc(page, key, ps, en, ur):
    f=DIR+f'p{page}.txt'; L=open(f,encoding='utf8').read().split('\n')
    i=next(k for k,l in enumerate(L) if l.startswith('q ') and key in l)
    j=i+1
    while j<len(L) and not (L[j].startswith('endtable') or re.match(r'q |qp |sol|##|@|p ',L[j])): j+=1
    if j<len(L) and L[j].startswith('endtable'): j+=1
    if j<len(L) and L[j].startswith('sol'): return
    L.insert(j,f'sol {ps} || {en} || {ur}')
    open(f,'w',encoding='utf8',newline='\n').write('\n'.join(L))
S=' (Derived from the poem\'s title and theme: the verses are not reproduced in this book data, so this is a general answer. Not verified against the printed key.)'
def G(page,key,theme_ps,theme_en,theme_ur):
    addc(page,key,theme_ps+' (Derived: د نظم عنوان او موضوع نه؛ شعرونه په دې کتاب ډېټا کښې نشته۔ Not verified)',theme_en+S,theme_ur+' (Derived؛ نظم کے اشعار یہاں موجود نہیں، Not verified)')
G('007','د دې حمد سیاق','دا حمد د الله تعالى د لوئي، رحمت او قدرت بیان دے او بنده په کښې الله تعالى ته ثنا او دعا کوي۔','This hamd describes the greatness, mercy and power of Allah, and the servant praises and prays to Allah.','یہ حمد اللہ کی عظمت، رحمت اور قدرت کا بیان ہے اور بندہ ثنا و دعا کرتا ہے۔')
G('007','د لاندې ورکړے شو شعرونو تشریح','په دې شعرونو کښې شاعر د الله تعالى د رحمت، کائنات د پېدا کولو او د بنده د عاجزۍ نه خبر ورکوي او ورته دعا کوي۔','In these verses the poet speaks of Allah\'s mercy, the creation of the universe and the servant\'s humility, and prays.','ان اشعار میں شاعر اللہ کی رحمت، تخلیقِ کائنات اور بندے کی عاجزی بیان کرتا اور دعا کرتا ہے۔')
G('008','د دې نظم خلاصه په روان','د دې حمد خلاصه دا ده چې الله تعالى یو دے، هر څۀ ورته ښکاره دي، هغه رحم کوونکے دے او مونږ باید یواځې هغه ته سجده وکړو او د هغه نه مدد وغواړو۔','Summary: Allah is One, nothing is hidden from Him, He is merciful, and we should bow only to Him and seek help from Him.','خلاصہ: اللہ ایک ہے، اس سے کچھ پوشیدہ نہیں، وہ رحم کرنے والا ہے اور ہمیں صرف اسی کو سجدہ کرنا اور اسی سے مدد مانگنی چاہیے۔')
G('016','په دې نعت کښې چې کوم اصطلاحات','په نعت کښې د حضور ﷺ ثنا او صفتونه، د مینې او درناوي اصطلاحات او د مدینې منورې یادونه راځي۔','The naat contains terms of praise for the Prophet ﷺ, of love and respect, and mention of Madina.','نعت میں نبی ﷺ کی مدح، محبت و ادب کی اصطلاحات اور مدینہ منورہ کا ذکر ہے۔')
G('016','د دې نعت خلاصه','د دې نعت خلاصه دا ده چې شاعر د حضور ﷺ د ښکلا، اخلاقو او احسانونو ثنا کوي او د هغوي ﷺ سره خپله مینه او د شفاعت هیله څرګندوي۔','Summary: the poet praises the beauty, character and favours of the Prophet ﷺ and expresses his love and hope for intercession.','خلاصہ: شاعر نبی ﷺ کے حسن، اخلاق اور احسانات کی مدح اور اپنی محبت و شفاعت کی امید ظاہر کرتا ہے۔')
G('016','د دې شعرونو لنډه','په دې شعرونو کښې شاعر د حضور ﷺ د مقام او د هغوي سره د امت د مینې نه خبر ورکوي او د دوي په لارې تلو ته هڅوي۔','In these verses the poet speaks of the Prophet\'s ﷺ rank and the Ummah\'s love for him and urges following his path.','ان اشعار میں شاعر نبی ﷺ کے مقام اور امت کی محبت کا ذکر کرتا اور ان کی راہ پر چلنے کی ترغیب دیتا ہے۔')
G('037','د دې بند تشریح وکړئ','په دې بند کښې شاعر ورور ولي ته بلنه ورکوي چې په خپلو کښې اتفاق او مینه وساتو، ځکه چې په یووالي کښې قوت دے۔','In this stanza the poet calls for brotherhood: keep unity and love among ourselves, because strength lies in unity.','اس بند میں شاعر بھائی چارے کی دعوت دیتا ہے: آپس میں اتفاق اور محبت رکھو کیونکہ طاقت اتحاد میں ہے۔')
G('058','د دې نظم مفهوم په خپلو لفظونو','د دې نظم مفهوم دا دے چې یو پښتون زلمے د خپل قام ننګ، غیرت، بهادرۍ او وطن ساتنې ته تیار دے او په خپل پښتون والي فخر کوي۔','The meaning: a Pashtun youth is ready for the honour, self-respect, bravery and defence of his people and homeland and takes pride in being a Pashtun.','مفہوم: پشتون نوجوان اپنی قوم کی غیرت، بہادری اور وطن کے دفاع کے لیے تیار ہے اور اپنے پشتون ہونے پر فخر کرتا ہے۔')
G('058','د لاندې ورکړې شوو شعرونو تشریح','په دې شعرونو کښې زلمے د پښتنو د ننګ، میړانې او د قام د خدمت د عزم اظهار کوي۔','In these verses the youth expresses the Pashtun honour, valour and resolve to serve the nation.','ان اشعار میں نوجوان پشتون غیرت، بہادری اور قوم کی خدمت کے عزم کا اظہار کرتا ہے۔')
G('080','د دې نظم خلاصه ولیکئ','د نظم خلاصه دا ده چې ماشومان د ملک راتلونکے دي، هغوي ته باید ښۀ تعلیم او تربیت ورکړے شي، او ماشومان باید لوبې او زده کړې دواړه وکړي۔','Summary: children are the future of the country; they should be given good education and training and should do both play and study.','خلاصہ: بچے ملک کا مستقبل ہیں، انہیں اچھی تعلیم و تربیت دی جائے اور وہ کھیل اور پڑھائی دونوں کریں۔')
G('080','د لاندې ورکړې شوو شعرونو تشریح','په دې شعرونو کښې شاعر ماشومانو ته د زده کړې، ښو اخلاقو او د مور پلار د خدمت نصیحت کوي۔','In these verses the poet advises children towards learning, good manners and serving their parents.','ان اشعار میں شاعر بچوں کو تعلیم، اچھے اخلاق اور والدین کی خدمت کی نصیحت کرتا ہے۔')
G('080','دا نظم په کوم هېښت','دا نظم د بندونو په شکل (بند وار) هېښت کښې دے۔','This poem is in stanza (band-wise) form.','یہ نظم بند وار ہیئت میں ہے۔')
G('102','دا نظم په کوم هېښت','دا نظم د بندونو په شکل (بند وار) هېښت کښې دے۔','This poem is in stanza (band-wise) form.','یہ نظم بند وار ہیئت میں ہے۔')
G('102','د دې بند تشریح په روان','په دې بند کښې شاعر ماشومانو ته ښۀ خویونه او ښۀ عادتونه اختیارولو او بد عادتونو پرېښودو نصیحت کوي۔','In this stanza the poet advises children to adopt good manners and habits and give up bad ones.','اس بند میں شاعر بچوں کو اچھے اخلاق و عادات اپنانے اور بری عادات چھوڑنے کی نصیحت کرتا ہے۔')
G('125','د لاندې ورکړې شوي بند تشریح','په دې بند کښې خوشحال خان د پښتنو د ننګ، ازادۍ او د قام د یووالي نه خبر ورکوي او ورته د تورې او قلم ټینګ نیولو ته هڅوي۔','In this stanza Khushal Khan speaks of Pashtun honour, freedom and unity and urges holding firmly to sword and pen.','اس بند میں خوشحال خان پشتون غیرت، آزادی اور اتحاد کی بات کرتا اور تلوار و قلم تھامنے کی ترغیب دیتا ہے۔')
G('146','د دې نظم خلاصه په خپلو','خلاصه دا ده چې د جینکو (خوېندو) تعلیم د کور او ټولې معاشرې د ترقۍ لپاره ضروري دے او خوېندې باید زده کړه وکړي۔','Summary: the education of girls (sisters) is necessary for the progress of the home and society, and sisters should study.','خلاصہ: بہنوں کی تعلیم گھر اور معاشرے کی ترقی کے لیے ضروری ہے اور انہیں پڑھنا چاہیے۔')
G('146','د دې بند تشریح ولیکئ','په دې بند کښې شاعر خوېندو ته د علم او هنر زده کولو او په خپلو پښو درېدو حوصله ورکوي۔','In this stanza the poet encourages sisters to learn knowledge and skills and stand on their own feet.','اس بند میں شاعر بہنوں کو علم و ہنر سیکھنے اور اپنے پاؤں پر کھڑے ہونے کا حوصلہ دیتا ہے۔')
G('175','د دې بندونو تشریح','په دې بندونو کښې شاعر د وطن د مینې، د هغې د ساتنې او په هغې د قربانۍ د جذبې نه خبر ورکوي۔','In these stanzas the poet speaks of love of the homeland, its defence and the spirit of sacrifice for it.','ان بندوں میں شاعر وطن کی محبت، اس کے دفاع اور قربانی کے جذبے کا ذکر کرتا ہے۔')
G('199','د دې بند تشریح ولیکئ','په دې بند کښې شاعر د مور پلار او مشرانو د عزت او خدمت ته هڅوي او وايي چې د هغوي رضا د الله رضا ده۔','In this stanza the poet urges respect and service of parents and elders, saying their pleasure is Allah\'s pleasure.','اس بند میں شاعر والدین اور بزرگوں کی عزت و خدمت کی تلقین کرتا اور ان کی رضا کو اللہ کی رضا بتاتا ہے۔')
